"OLAYLAR_FRANSA_KONTROL_1027:1798-03-15:0":{"b": ["मुलहाउज़ गणराज्य फ़्रांस गणराज्य में मिला (रेयूनियों)", "0c2b4f8a"], "d": ["1515 से स्विस परिसंघ के सहयोगी रहे मुलहाउज़ गणराज्य ने बेज़ल की शांति (1795) के बाद स्वेच्छा से फ़्रांस से मिलना स्वीकार किया; विलय 1798 में हुआ (रेयूनियों)।", "e775b26b"]},
"OLAYLAR_FRANSA_KONTROL_1027:1814-05-30:0":{"b": ["पेरिस की संधि: मोनाको ग्रिमाल्दी की संप्रभुता में लौटा", "f3011157"], "d": ["30 मई 1814 की पेरिस संधि से ग्रिमाल्दियों के अधिकार लौटाए गए; मोनाको फ़्रांसीसी विलय से निकला (1815–1861 का सार्दीनियाई संरक्षण अलग विषय है, इस अभिलेख में नहीं लिया गया)। इस संधि से मांतों (मोनाको रियासत) ग्रिमाल्दी की संप्रभुता में लौटा।", "91de9178"]},
"OLAYLAR_FRANSA_KONTROL_1027:1861-02-02:0":{"b": ["फ़्रांस-मोनाको संधि: मोनाको ने मांतों (और रोकब्रून) पर अपने अधिकार 4 मिलियन फ़्रैंक के बदले छोड़े; मांतों फ़्रांस को गया", "ffa21e54"], "d": ["पीडमॉन्ट-सार्दीनिया के 1860 में नीस के साथ फ़्रांस को सौंपने के बाद मोनाको के राजकुमार ने मांतों और रोकब्रून में संप्रभुता के अधिकार फ़्रांस को सौंपे। मांतों 1848 से स्वतंत्र नगर था, सार्दीनियाई संरक्षण में।", "0aff978e"]},
"OLAYLAR_FRANSA_KONTROL_1027:1918-11-17:0":{"b": ["फ़्रांसीसी टुकड़ियाँ मुलहाउज़ में घुसीं: एल्सास की वापसी आरंभ हुई", "a56edca7"], "d": ["युद्धविराम (11 नवंबर 1918) के छह दिन बाद फ़्रांसीसी टुकड़ियाँ मुलहाउज़ में घुसीं। वर्साय धारा 51 एल्सास-लोरेन के फ़्रांसीसी संप्रभुता में लौटने को 11 नवंबर 1918 से पीछे की ओर लागू मानती है; हस्ताक्षर 28 जून 1919, प्रवर्तन 10 जनवरी 1920।", "204a7d28"]},
